import logging

class LoggingConfigurator:
    def __init__(self, config):
        self.config = config
        self.handlers = {}

    def add_handler(self, handler_name, handler_settings):
        self.handlers[handler_name] = handler_settings

    def set_level(self, handler_name, level):
        if handler_name in self.handlers:
            self.handlers[handler_name]['level'] = level
        else:
            raise ValueError(f"Handler '{handler_name}' does not exist.")

    def configure_logging(self):
        for handler_name, settings in self.handlers.items():
            handler_class = settings.get('class')
            level = settings.get('level')
            formatter = settings.get('formatter')

            if handler_class == 'logging.StreamHandler':
                handler = logging.StreamHandler()
            elif handler_class == 'logging.FileHandler':
                handler = logging.FileHandler('app.log')
            else:
                raise ValueError(f"Unsupported handler class: {handler_class}")

            handler.setLevel(getattr(logging, level))
            handler.setFormatter(logging.Formatter(formatter))
            logging.getLogger().addHandler(handler)

